    pub fn solve(queries: Vec<i8>) -> Vec<i8> {
        let mut results: Vec<i8> = Vec::with_capacity(queries.len());
        let mut i: usize = 0;

        // Loop invariant: we've processed [0 .. i), and
        // results.len() == i, and for all j < i, results[j] satisfies f(queries[j]).
        while i < queries.len() {
            decreases(queries.len() - i);
            invariant!(results.len() == i);
            invariant!({
                forall(|j: usize|
                    j < results.len() ==>
                        results[j] ==
                          if queries[j] >= 4 {
                              queries[j] % 2
                          } else {
                              4 - queries[j]
                          }
                )
            });

            let n = queries[i];
            let x: i8 =
                if n >= 4 {
                    // Since n ≥ 4 and n is positive, n % 2 is 0 or 1
                    n % 2
                } else {
                    // 2 ≤ n < 4, so 4 - n is 1 or 2
                    4 - n
                };
            results.push(x);
            i += 1;
        }

        results
    }

